  'editor.anim.reproducir': 'Putar animasi',
  'editor.anim.pausar': 'Jeda animasi',
  'editor.pers.anim': 'Animasi',
  'editor.pers.animFlote': 'Gerakan menggantikan gerak melayang alami karakter; lambaian tangan tetap ada.',
  'editor.pers.animSinPiezas': 'Untuk membuat animasi pose, bangun tubuhnya dengan bagian 3D di tab Tubuh.',
  'room.cocina.desc': 'Nutrisi: catat makananmu, makro, air minum, dan rencana mingguanmu.',
  'room.ejercicio.desc': 'Rutinitas kekuatan, daya tahan, dan fleksibilitas dengan target.',
  'room.recamara.desc': 'Pantau istirahatmu dan tulis buku kenangan pribadimu.',
  'room.descanso.desc': 'Tidurmu sebagai langit malam: jadwal, alarm, skor, dan catatan malam.',
  'room.anecdotario.desc': 'Buku kenanganmu: kenangan dengan foto dan suasana hati harian.',
  'room.despacho.desc':
    'Keuangan: anggaran dengan pengeluaran dan pemasukan (tetap dan variabel), target (kalkulator finansial, tabungan/investasi, utang) dengan simulator, dan pasar langsung.',
  'room.biblioteca.desc': 'Ensiklopedia percakapan: obrolan AI, entri wiki, dan sesi belajar.',
  'room.entretenimiento.desc': 'Arsip film, serial, buku, dan permainan papan.',
  'room.sala.desc': 'Rencanakan perjalanan: itinerary, pengeluaran, daftar periksa, dan daftar keinginan.',
  'room.jardin.desc': 'Ketenangan: meditasi terpandu, latihan napas, dan jurnal rasa syukur.',
  'room.garage.desc': 'Perawatan kendaraanmu dan servisnya.',
  'room.diario.desc': 'Pusat berita harian, berdasarkan kategori.',
  'room.hobbies.desc': 'Hobi dan proyek kreatifmu.',
  'room.idiomas.desc': 'Belajar bahasa: tutor AI, kosakata pengulangan berjarak, silabus tingkat, dan latihan.',
  'room.calendario.desc': 'Kalendermu: acara dan rutinitas per hari, minggu, dan bulan.',
  'room.caminos.desc': 'Buat lintasan balap, rel kereta, dan roller coaster di peta.',
  'room.canchas.desc': 'Tempatkan lapangan sepak bola, tenis, basket, dan bisbol di peta.',
  'room.huerto.desc': 'Siapkan petak, tanam bibit, siram, dan panen secara real-time.',
  'room.granja.desc': 'Pelihara ayam, babi, kambing, domba, sapi, dan kuda, serta tanam pakannya di editor yang sama.',
  'room.ideas.desc':
    'Jurnal ide dan curah gagasanmu, sepuluh format peta konsep di kanvas bebas (peta pikiran, pohon, linimasa, siklus, piramida, Venn…) dan delapan diagram untuk mengambil keputusan (kelebihan dan kekurangan, force field, SWOT, Eisenhower, pohon keputusan, tier list, matriks keputusan berbobot, dan Ishikawa), dengan tangan atau dengan AI.',
  'room.metas.desc':
    'Apa yang kamu tetapkan untuk dirimu, dari seluruh rumah: daftar target beserta sub-target dan langkah-langkahnya, rencana yang diusulkan AI untuk masing-masing (fase bertanggal yang berubah menjadi sub-target sungguhan), dan linimasa tempat semuanya menempati periodenya di sumbu waktu.',
  'room.computo.desc':
    'Ruang komputer: kalkulator ilmiah dengan buku rumus yang menggantung di sampingnya (Matematika, Fisika, dan Kimia sudah ada dan bisa diedit) serta delapan mode — plotter dengan empat jenis (2D, polar, parametrik, dan permukaan 3D), biner dan heksadesimal, matriks, sistem persamaan, konversi satuan, tip, dan aturan tiga; juga spreadsheet yang bisa diekspor ke Excel dan PDF.',
