  'ideas.tipoDesc.matriz': 'Beberapa pilihan dinilai berdasarkan kriteria yang benar-benar kamu pedulikan.',
  'ideas.guia.matriz':
    'Setiap kriteria memiliki bobot sesuai seberapa penting bagimu (1-5) dan setiap pilihan dinilai 1 sampai 5 untuk kriteria itu. Totalnya mengalikan nilai dengan bobot, jadi tidak ada yang menang hanya karena unggul di hal yang tidak kamu pedulikan.',
  'ideas.matriz.criterio': 'Kriteria',
